#pragma once
#include "core.hpp"
#include <algorithm>
#include <condition_variable>
#include <mutex>
#include <thread>
#include <memory>
namespace obj {
struct DepthJob {bool has_priority_roi=false;Box priority_roi;int selected=-1;Frame frame;std::vector<int>ids;std::vector<uint32_t>generations;std::vector<Box>boxes;};
struct DepthResult {uint64_t epoch=0,frame=0,time=0;double processing_ms=0;int rows=0,full_rows=0;bool selected_roi=false;std::vector<int>ids;std::vector<uint32_t>generations;std::vector<Point>points;std::string reason="DEPTH_PENDING";};
class StereoWorker {
 Calibration calibration;Config config;std::thread thread;std::mutex mutex;std::condition_variable cv;bool quit=false;std::unique_ptr<DepthJob>pending;std::shared_ptr<const DepthResult>result;uint64_t submitted=0,replaced=0,completed=0;
 void run(){for(;;){std::unique_ptr<DepthJob>job;{std::unique_lock<std::mutex>lock(mutex);cv.wait(lock,[&]{return quit||pending;});if(quit)return;job=std::move(pending);}auto output=std::make_shared<DepthResult>();output->epoch=job->frame.epoch;output->frame=job->frame.id;output->time=job->frame.time;output->ids=job->ids;output->generations=job->generations;auto begin=now_us();try{bool roi=job->has_priority_roi;Depth depth=roi?stereo_roi(job->frame,calibration,config,job->priority_roi):stereo(job->frame,calibration,config);output->rows=depth.row_end-depth.row_begin;output->full_rows=depth.h;output->selected_roi=roi;for(size_t bi=0;bi<job->boxes.size();bi++){const auto&box=job->boxes[bi];Point p;if(!roi||job->ids[bi]==job->selected)p=associate(box,depth,calibration,config);else p.reason="DEPTH_SELECTED_ROI_PRIORITY";p.source_frame=job->frame.id;p.source_time=job->frame.time;p.source_eye=box.eye;p.source_box=box;p.geometry_eye=calibration.left_eye;output->points.push_back(p);}output->reason=roi&&std::find(job->ids.begin(),job->ids.end(),job->selected)==job->ids.end()?"DEPTH_LOST_SELECTED_ROI_NO_IDENTITY_MEASUREMENT":"DEPTH_READY";}catch(const std::exception&e){output->reason=e.what();output->points.assign(job->boxes.size(),Point{});for(auto&p:output->points)p.reason=output->reason;}output->processing_ms=(now_us()-begin)/1000.;{std::lock_guard<std::mutex>lock(mutex);result=std::move(output);completed++;}}}
 public:StereoWorker(const Calibration&c,const Config&cfg):calibration(c),config(cfg){thread=std::thread([this]{run();});}~StereoWorker(){{std::lock_guard<std::mutex>lock(mutex);quit=true;pending.reset();}cv.notify_all();thread.join();}
 void submit(const Frame&f,const Tracker&t){auto job=std::make_unique<DepthJob>();job->frame=f;job->selected=t.selected;for(const auto&tr:t.tracks)if(tr.id==t.selected){job->has_priority_roi=true;job->priority_roi=tr.reacquire_candidate_valid?tr.reacquire_candidate_box:tr.observed?tr.last_observed_box:tr.box;}for(const auto&tr:t.tracks)if(tr.observed&&tr.last_frame==f.id){job->ids.push_back(tr.id);job->generations.push_back(tr.binding_generation);job->boxes.push_back(tr.last_observed_box);}std::lock_guard<std::mutex>lock(mutex);if(pending)replaced++;pending=std::move(job);submitted++;cv.notify_one();}
 std::shared_ptr<const DepthResult>latest(Vision&v){std::lock_guard<std::mutex>lock(mutex);v.submitted=submitted;v.replaced=replaced;v.completed=completed;if(result){v.roi_rows=result->rows;v.full_rows=result->full_rows;v.selected_roi=result->selected_roi;}return result;}
};
inline bool apply_depth_result(Tracker&t,const DepthResult&r,uint64_t epoch,uint64_t now,double max_age_ms){if(r.epoch!=epoch||r.time>now||now-r.time>(uint64_t)(max_age_ms*1000)||r.ids.size()!=r.points.size())return false;bool any=false;for(size_t i=0;i<r.ids.size();i++)for(auto&tr:t.tracks)if(tr.id==r.ids[i]){const Point&p=r.points[i];if((!r.generations.empty()&&(r.generations.size()!=r.ids.size()||r.generations[i]!=tr.binding_generation))||p.source_time<tr.binding_source_us||p.source_time<tr.last_point.source_time)continue;if(p.valid||p.candidate_count){tr.last_point=p;tr.point=p;tr.coarse=p;any=true;}else if(!tr.last_point.valid){tr.point.reason=tr.last_point.reason=p.reason;}}return any;}
}
